/** Original Zhouyi text of one hexagram, generated by scripts/fetch-classics.ts. */
export interface ClassicText {
  number: number;
  /** 卦辞 */
  judgment: string;
  /** 彖传 */
  tuan: string;
  /** 大象传 */
  image: string;
  /** 爻辞 from bottom to top. 乾 and 坤 have a seventh entry, 用九 and 用六. */
  lines: ClassicLine[];
}

export interface ClassicLine {
  label: string;
  text: string;
  /** 小象传 */
  image: string;
}

/** Beginner-oriented explanation of one hexagram. */
export interface Guide {
  number: number;
  /** The theme of the hexagram in at most six characters. */
  keyword: string;
  summary: string;
  /** Paragraphs that introduce the name, the picture of the two trigrams and the situation. */
  overview: string[];
  judgmentPlain: string;
  judgmentNote: string;
  tuanPlain: string;
  imagePlain: string;
  /** One entry per entry of ClassicText.lines, in the same order. */
  lines: GuideLine[];
  advice: string[];
  glossary: GlossaryEntry[];
}

export interface GuideLine {
  plain: string;
  note: string;
}

export interface GlossaryEntry {
  term: string;
  pinyin?: string;
  meaning: string;
}

/** Summary of Ni Haixia's teaching on one hexagram, with the sources it was compiled from. */
export type NiCommentary = NiCommentaryAvailable | NiCommentaryMissing;

export interface NiCommentaryAvailable {
  number: number;
  status: 'available';
  /** 卦图象解: how he reads the traditional picture that accompanies the hexagram. */
  imageReading?: {
    scene: string;
    motto?: string;
    points: string[];
  };
  /** 人间道: his reading of the hexagram as guidance for conduct. */
  humanWay: {
    summary: string;
    judgment: string;
    /** One entry per line from bottom to top, or empty when the source has no line-by-line text. */
    lines: string[];
  };
  /** Divination remarks from his 先天卦, 后天卦 and 流年卦 readings. */
  divination?: string[];
  sources: Source[];
  note?: string;
}

export interface NiCommentaryMissing {
  number: number;
  status: 'missing';
  note: string;
}

export interface Source {
  title: string;
  url: string;
}
